css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-rw{width:min(1080px,100%);display:grid;gap:2em}
.fx-rw .top{display:flex;justify-content:space-between;align-items:end;gap:1em 2em;flex-wrap:wrap}
.fx-rw h2{font-size:clamp(1.8em,4vw,2.7em);max-width:16ch}
.fx-rw .sum{display:flex;align-items:center;gap:.9em}.fx-rw .sum b{font:600 2.6em/1 var(--font-heading)}
.fx-rw .sum span{display:grid;font-size:.88em;opacity:.7}.fx-rw .sum em{font-style:normal;color:var(--accent);letter-spacing:.1em}
.fx-rw .wall{column-count:3;column-gap:1.1em}
.fx-rw .rv{break-inside:avoid;margin:0 0 1.1em;padding:1.3em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text));display:grid;gap:.6em;transition:transform calc(.3s/var(--speed)),box-shadow calc(.3s/var(--speed)),border-color .3s}
.fx-rw .rv:hover{transform:translateY(-3px);border-color:color-mix(in srgb,var(--accent) 50%,var(--border));box-shadow:0 18px 28px -22px color-mix(in srgb,var(--text) 60%,transparent)}
.fx-rw .st{color:var(--accent);letter-spacing:.12em;font-size:.95em}
.fx-rw h3{font-size:1.12em}.fx-rw .rv p{opacity:.74;font-size:.94em}
.fx-rw footer{display:flex;align-items:center;gap:.7em;margin-top:.3em;font-size:.88em}
.fx-rw .av{width:2.3em;height:2.3em;border-radius:50%;flex:none}.fx-rw .av::before,.fx-rw .av::after{display:none}
.fx-rw footer b{display:block}.fx-rw footer small{opacity:.6}
@media(max-width:860px){.fx-rw .wall{column-count:2}}
@media(max-width:520px){.fx-rw .wall{column-count:1}}
@media(prefers-reduced-motion:reduce){.fx-rw .rv{transition:none}.fx-rw .rv:hover{transform:none}
.fx-rw .rv.is-tap{transform:none}}
/* touch: :hover mirrored as .is-tap */
.fx-rw .rv.is-tap{transform:translateY(-3px);border-color:color-mix(in srgb,var(--accent) 50%,var(--border));box-shadow:0 18px 28px -22px color-mix(in srgb,var(--text) 60%,transparent)}
